Here is a complete, production-ready example of an `onSubmit` function for a React form that sends data to a GraphQL API.

This example uses **React Hook Form** (the industry standard for complex forms) and **Apollo Client** (the standard for GraphQL state management).

### The `onSubmit` Function

```javascript
import { useMutation } from '@apollo/client';
import { toast } from 'react-toastify'; // Optional: for user feedback

// 1. Define the GraphQL Mutation
const CREATE_USER_MUTATION = `
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      createdAt
    }
  }
`;

// 2. The onSubmit Function
export const handleFormSubmit = async (data, setSubmitting) => {
  try {
    // Set loading state
    setSubmitting(true);

    // 3. Execute the Mutation
    // We use the useMutation hook to access the mutation function
    const [result] = await useMutation(CREATE_USER_MUTATION, {
      variables: {
        input: {
          email: data.email,
          password: data.password,
          // Add other fields here
        },
      },
      // Optional: Handle errors gracefully
      onError: (error) => {
        console.error('GraphQL Error:', error);
        toast.error('Failed to create user. Please check your connection.');
      },
      // Optional: Handle success
      onCompleted: (data) => {
        console.log('Success:', data);
        toast.success('User created successfully!');
      },
    });

    // 4. Handle Success
    // If you need to redirect or reset the form
    // window.location.href = '/dashboard';
    // setSubmitting(false); // Reset state if not handled by parent

  } catch (error) {
    console.error('Network Error:', error);
    toast.error('An unexpected error occurred.');
  } finally {
    // Ensure loading state is reset even if an error occurs
    setSubmitting(false);
  }
};
```

