 * Packs an array of entities into a compact ArrayBuffer.
 * 
 * @param {Array} entities - Array of objects with { id: number, size: number }
 * @returns {ArrayBuffer} - The packed buffer
 */
function packEntities(entities) {
    if (!entities || entities.length === 0) {
        return new ArrayBuffer(0);
    }

    // Calculate total bits needed: entities.length * 7 bits
    const totalBits = entities.length * 7;
    // Convert bits to bytes (ceiling)
    const byteLength = Math.ceil(totalBits / 8);

    // Create a Uint8Array to act as our bit-buffer
    const buffer = new Uint8Array(byteLength);
    let bitOffset = 0;

    for (const entity of entities) {
        // Validate inputs (optional but recommended)
        if (entity.id > 15 || entity.size > 7) {
            throw new Error("Entity fields exceed 4 bits (id) or 3 bits (size)");
        }

        // Move the bit pointer forward by 7 bits
        bitOffset += 7;

        // Pack ID (4 bits) and Size (3 bits)
        // We construct the 7-bit integer: (id << 3) | size
