    const hotels = result.rows.map(h => ({
      id: h.id,
      name: h.name,
      city: h.city,
      country: h.country,
      rating: h.rating
    }));

    res.json({ results: hotels });

  } catch (error) {
    console.error('Database Error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
