// NewGoogleDomainsSolver creates a new solver instance
func NewGoogleDomainsSolver(apiKey, email string) (*GoogleDomainsSolver, error) {
	// Create the HTTP client with the API Key
	client := &http.Client{}

	// Initialize the Google Domains API client
	// Note: We use the API Key directly in the Authorization header
	gdClient, err := domains.New(client, oauth2.NoContext)
	if err != nil {
		return nil, fmt.Errorf("failed to create Google Domains client: %w", err)
	}

	// Set the API Key in the client's transport or headers
	// The Google Domains API expects the key in the 'Authorization' header
	// However, the standard client doesn't handle custom auth easily without a custom transport.
	// We will handle the auth in the specific request methods.

	return &GoogleDomainsSolver{
		apiKey: apiKey,
		email:  email,
		client: gdClient,
	}, nil
}

