To write a simple Node.js program that receives a file from a user and returns a hash of the file, you can use the `crypto` module to compute the hash and the `fs` module to read the file. Here is a basic example:

```javascript
const crypto = require('crypto');
const fs = require('fs');

function hashFile(filePath) {
    const hash = crypto.createHash('sha256');
    const fileStream = fs.createReadStream(filePath);
    fileStream.on('data', (chunk) => {
        hash.update(chunk);
    });
    fileStream.on('end', () => {
        console.log('Hash:', hash.digest('hex'));
    });
}

// Example usage
hashFile('path/to/your/file.txt');
```

